#include "script_component.hpp"
/* ----------------------------------------------------------------------------
Internal Function: CBA_fnc_init

Description:
    Runs Init and InitPost event handlers on this object.
    Internal use only.

Parameters:
    0: Any CfgVehicles object <OBJECT>

Returns:
    None

Examples:
    (begin example)
        [_unit] call CBA_fnc_init;
    (end)

Author:
    commy2
---------------------------------------------------------------------------- */

params ["_object"];

if (_object call CBA_fnc_isTerrainObject) exitWith {
    INFO_2("Abort init event for terrain object %1. Class: %2.",_object,typeOf _object);
};

if !(ISINITIALIZED(_object)) then {
    SETINITIALIZED(_object);

    // run Init
    {
        [_object] call _x;
    } forEach (_object getVariable QGVAR(init));

    // run InitPost or put on stack
    if (SLX_XEH_MACHINE select 8) then {
        [{
            {
                [_this] call _x;
            } forEach (_this getVariable QGVAR(initPost));
        }, _object] call CBA_fnc_execNextFrame;
    } else {
        GVAR(initPostStack) pushBack _object;
    };

    // fix for respawnVehicle clearing the object namespace
    _object addEventHandler ["Respawn", {
        params ["_vehicle", "_wreck"];

        if (ISINITIALIZED(_vehicle)) exitWith {}; // Exit if unit respawned normaly with copied variables (e.g. humans)
        SETINITIALIZED(_vehicle);

        {
            private ["_vehicle", "_wreck"]; // prevent these variables from being overwritten
            call _x;
        } forEach (_wreck getVariable QGVAR(respawn));

        {
            private _varName = format [QGVAR(%1), _x];
            private _events = _vehicle getVariable _varName;

            if (!isNil "_events") then {
                _vehicle setVariable [_varName, _events, true];
            };
        } forEach [XEH_EVENTS];
    }];

    #ifdef DEBUG_MODE_FULL
        diag_log ["Init", _unit, local _unit, typeOf _unit];
    #endif
};

#include "script_component.hpp"
/* ----------------------------------------------------------------------------
Internal Function: CBA_fnc_initEvents

Description:
    Adds all event handlers to this object.
    Internal use only.

Parameters:
    0: Any CfgVehicles object <OBJECT>

Returns:
    None

Examples:
    (begin example)
        _unit call CBA_fnc_initEvents;
    (end)

Author:
    commy2
---------------------------------------------------------------------------- */

params ["_unit"];

if !(ISPROCESSED(_unit)) then {
    SETPROCESSED(_unit);

    private _class = configOf _unit;
    private _eventClass = _class >> "EventHandlers" >> QUOTE(XEH_CLASS);

    // adds ability to disable XEH completely on a unit, by manually clearing the CBA event handler class.
    if (isClass _eventClass && {configProperties [_eventClass] isEqualTo []}) exitWith {};

    // add events to XEH incompatible units
    if (!isClass _eventClass) then {
        {
            _unit addEventHandler [_x, format ['call FUNC(%1)', _x]];
        } forEach ([XEH_EVENTS] - ["FiredBis", "InitPost"]);
    };

    while {isClass _class} do {
        private _className = configName _class;

        // add other event handlers
        {
            private _eventName = _x;
            private _eventVarName = format [QGVAR(%1), _eventName];

            {
                if (ISKINDOF(_unit,configName _class,_x select 1,_x select 2)) then {
                    if (isNil {_unit getVariable _eventVarName}) then {
                        _unit setVariable [_eventVarName, []];
                    };

                    (_unit getVariable _eventVarName) pushBack (_x select 0);
                };
            } forEach EVENTHANDLERS(_eventName,_className);
        } forEach (missionNamespace getVariable [format [QGVAR(::%1), _className], []]); // flags

        _class = inheritsFrom _class;
    };
};

#include "script_component.hpp"
/* ----------------------------------------------------------------------------
Function: CBA_fnc_addClassEventHandler

Description:
    Add an eventhandler to a class and all children.

Parameters:
    0: _className        - The classname of objects you wish to add the eventhandler too. Can be a base class. <STRING>
    1: _eventName        - The type of the eventhandler. E.g. "init", "fired", "killed" etc. <STRING>
    2: _eventFunc        - Function to execute when event happens. <CODE>
    3: _allowInheritance - Allow event for objects that only inherit from the given classname? (optional) <BOOLEAN> (default: true)
    4: _excludedClasses  - Exclude these classes from this event including their children (optional) <ARRAY> (default: [])
    5: _applyInitRetroactively - Apply "init" event type on existing units that have already been initilized. (optional) <BOOLEAN> ((default: false)

Returns:
    _success - Whether adding the event was successful or not. <BOOLEAN>

Examples:
    (begin example)
        ["CAManBase", "fired", {systemChat str _this}] call CBA_fnc_addClassEventHandler;
        ["All", "init", {systemChat str _this}] call CBA_fnc_addClassEventHandler;
        ["Car", "init", {(_this select 0) engineOn true}, true, [], true] call CBA_fnc_addClassEventHandler; //Starts all current cars and those created later
    (end)

Author:
    commy2
---------------------------------------------------------------------------- */

params [["_className", "", [""]], ["_eventName", "", [""]], ["_eventFunc", {}, [{}]], ["_allowInheritance", true, [false]], ["_excludedClasses", [], [[]]], ["_applyInitRetroactively", false, [false]]];

private _config = configFile >> "CfgVehicles" >> _className;

// init fallback loop when executing on incompatible class for the first time
if (!GVAR(fallbackRunning) && {ISINCOMP(_className)}) then {
    WARNING_1("One or more children of class %1 do not support Extended Event Handlers. Fall back to loop.",configName _config);
    call CBA_fnc_startFallbackLoop;
};

// no such CfgVehicles class
if (!isClass _config) exitWith {false};

_eventName = toLower _eventName;

// no such event
if (_eventName == "FiredBIS") exitWith {
    WARNING("Cannot add ""FiredBIS"" - Use ""Fired"" instead.");
    false
};
if !(_eventName in GVAR(EventsLowercase)) exitWith {false};

// don't use "apply retroactively" for non init events
if (_applyInitRetroactively && {!(_eventName in ["init", "initpost"])}) then {
    _applyInitRetroactively = false;
};

// add events to already existing objects
private _eventVarName = format [QGVAR(%1), _eventName];

private _entities = (entities [[], [], true, false]); // include dead entities to handle respawning units
_entities = _entities arrayIntersect _entities; // entities can return duplicates at postInit - #567

{
    if (_x isKindOf _className) then {
        private _unit = _x;

        if (ISKINDOF(_unit,_className,_allowInheritance,_excludedClasses)) then {
            if (isNil {_unit getVariable _eventVarName}) then {
                _unit setVariable [_eventVarName, []];
            };

            (_unit getVariable _eventVarName) pushBack _eventFunc;

            //Run initReto now if the unit has already been initialized
            if (_applyInitRetroactively && {ISINITIALIZED(_unit)}) then {
                // If PostInit has not finished exit as it will be run via initPostStack
                if ((_eventName == "initpost") && {!(SLX_XEH_MACHINE select 8)}) exitWith {};
                [_unit] call _eventFunc;
            };
        };
    };
} forEach _entities;

// define for units that are created later
private _events = EVENTHANDLERS(_eventName,_className);

_events pushBack [_eventFunc, _allowInheritance, _excludedClasses];

SETEVENTHANDLERS(_eventName,_className,_events);

// set flag for this event handler to be used on this class. reduces overhead on init.
private _eventNameFlagsVarName = format [QGVAR(::%1), _className];
private _eventNameFlags = missionNamespace getVariable [_eventNameFlagsVarName, []];

if !(_eventName in _eventNameFlags) then {
    _eventNameFlags pushBack _eventName;
    missionNamespace setVariable [_eventNameFlagsVarName, _eventNameFlags];
};

true

#include "script_component.hpp"
/* ----------------------------------------------------------------------------
Function: CBA_fnc_compileEventHandlers

Description:
    Compiles all Extended EventHandlers in given config.

Parameters:
    0: _baseConfig - What config file should be used. <CONFIG>

Returns:
    Compiled code of all Extended EventHandlers <ARRAY>
        format: [event1, event2, ..., eventN] <ARRAY>
        eventX format: [_className <STRING>, _eventName <STRING>, _eventFunc <CODE>, _allowInheritance <BOOLEAN>, _excludedClasses <ARRAY>]

Examples:
    (begin example)
        configFile call CBA_fnc_compileEventHandlers;
    (end)

Author:
    commy2
---------------------------------------------------------------------------- */

params [["_baseConfig", configNull, [configNull]]];

private _result = [];
private _resultNames = [];

private _allowRecompile = _baseConfig isEqualTo configFile;

if (_allowRecompile) then {
    if ("compile" call CBA_fnc_isRecompileEnabled || {isFilePatchingEnabled}) then {
        XEH_LOG("init function preProcessing disabled [recompile or filepatching enabled]");
        _allowRecompile = false;
    };
};

// note: format is never used for config parsing here, because of its 8192 character limitation.

{
    private _eventName = _x;

    {
        private _funcAll = "";
        private _funcClient = "";
        private _funcServer = "";
        private _customName = configName _x;

        if (isClass _x) then {
            // events on clients and server
            private _entry = _x >> "init";

            if (isText _entry) then {
                _funcAll = getText _entry;
            };

            // client only events
            _entry = _x >> "clientInit";
            if (isText _entry) then {
                _funcClient = getText _entry;
            };

            // server only events
            _entry = _x >> "serverInit";
            if (isText _entry) then {
                _funcServer = getText _entry;
            };
        } else {
            // global events
            if (isText _x) then {
                _funcAll = getText _x;
            };
        };

        private _eventFuncs = [_funcAll, _funcClient, _funcServer] apply {
            if (_x == "") then {
                TRACE_2("does NOT do something",_customName,_eventName);
                {} // apply return
            } else {
                TRACE_2("does something",_customName,_eventName);
                private _eventFunc = _x;

                //Optimize "QUOTE(call COMPILE_FILE(XEH_preInit));" down to just the content of the EH script
                if (_allowRecompile) then {
                    if (toLower (_eventFunc select [0,40]) isEqualTo "call compile preprocessfilelinenumbers '" && {(_eventFunc select [count _eventFunc - 1]) isEqualTo "'"}) then {
                        private _funcPath = _eventFunc select [40, count _eventFunc - 41];

                        //If there is a quote mark in the path, then something went wrong and we got multiple paths, just skip optimization
                        //Example cause: "call COMPILE_FILE(XEH_preInit);call COMPILE_FILE(XEH_preClientInit)"
                        if (_funcPath find "'" == -1) then {
                            _eventFunc = compileScript [_funcPath];
                            TRACE_2("eventfunction redirected",_customName,_funcPath);
                        };
                    };
                    // if (_eventFunc isEqualTo _x) then { diag_log text format ["XEH: Could not recompile [%1-%2]: %3", _eventName, _customName, _eventFunc]; };
                };
                if (_eventFunc isEqualType "") then {
                    _eventFunc = compile _eventFunc;
                };
                _eventFunc // apply return
            };
        };

        _result pushBack ["", _eventName, _eventFuncs];
        _resultNames pushBack _customName;
    } forEach configProperties [_baseConfig >> XEH_FORMAT_CONFIG_NAME(_eventName)];
} forEach ["preInit", "postInit"];

// object events
{
    private _eventName = _x;

    {
        private _entryName = _eventName; // how the entries are labeled, e.g. init, serverInit

        private _className = configName _x;
        private _eventFuncBase = "";

        if (_eventName == "initPost") then {
            _entryName = "init";
        };

        // backwards compatibility
        if (_eventName == "fired") then {
            // generate backwards compatible format of _this
            _eventFuncBase = "private _this = [_this select 0, _this select 1, _this select 2, _this select 3, _this select 4, _this select 6, _this select 5];";
            WARNING_4("Usage of deprecated Extended Event Handler ""fired"". Use ""firedBIS"" instead. Path: %1\%2\%3\%4.",configSourceMod _x,_baseConfig,XEH_FORMAT_CONFIG_NAME(_eventName),_className);
        };

        {
            private _customName = configName _x;
            private _allowInheritance = true;
            private _excludedClasses = [];
            private _funcAll = "";
            private _funcClient = "";
            private _funcServer = "";

            if (isClass _x) then {
                // allow inheritance of this event?
                private _scope = _x >> "scope";

                if (isNumber _scope) then {
                    _allowInheritance = getNumber _scope != 0;
                };

                // init event handlers that should run on respawn again, onRespawn = 1
                private _onRespawn = toLower _eventName in ["init", "initpost"] && {getNumber (_x >> "onRespawn") == 1};

                // classes excluded from this event
                private _exclude = _x >> "exclude";

                if (isArray _exclude) then {
                    _excludedClasses append getArray _exclude;
                };

                if (isText _exclude) then {
                    _excludedClasses pushBack getText _exclude;
                };

                // events on clients and server
                private _entry = _x >> _entryName;

                if (isText _entry) then {
                    _funcAll = _eventFuncBase + getText _entry + ";";

                    if (_onRespawn) then {
                        _funcAll = _funcAll + "(_this select 0) addEventHandler ['Respawn', " + str _funcAll + "];";
                    };
                };

                // client only events
                _entry = _x >> format ["client%1", _entryName];

                if (isText _entry) then {
                    _funcClient = _eventFuncBase + getText _entry + ";";

                    if (_onRespawn) then {
                        _funcClient = _funcClient + "(_this select 0) addEventHandler ['Respawn', " + str _funcClient + "];";
                    };
                };

                // server only events
                _entry = _x >> format ["server%1", _entryName];

                if (isText _entry) then {
                    _funcServer = _eventFuncBase + getText _entry + ";";

                    if (_onRespawn) then {
                        _funcServer = _funcServer + "(_this select 0) addEventHandler ['Respawn', " + str _funcServer + "];";
                    };
                };
            } else {
                // global events
                if (isText _x) then {
                    _funcAll = _eventFuncBase + getText _x + ";";
                };
            };

            // emulate oo-like inheritance by adding classnames that would redefine an event by using the same custom event name to the excluded classes
            {
                (_result select _forEachIndex) params ["_classNameX", "_eventNameX"];

                // same custom name and same event type
                if (_customName == _x && {_eventName == _eventNameX}) then {
                    // has parent already set, update parent to exclude this class
                    if (_className isKindOf _classNameX) then {
                        (_result select _forEachIndex select 4) pushBack _className;
                    };

                    // has child already set, add child to excluded classes
                    if (_classNameX isKindOf _className) then {
                        _excludedClasses pushBack _classNameX;
                    };
                };
            } forEach _resultNames;

            private _eventFuncs = [_funcAll, _funcClient, _funcServer] apply {
                // only add event on machines where it exists
                if (_x == "") then {
                    TRACE_3("does NOT do something",_customName,_className,_eventName);
                    {}
                } else {
                    TRACE_3("does something",_customName,_className,_eventName);
                    compile _x
                };
            };
            _result pushBack [_className, _eventName, _eventFuncs, _allowInheritance, _excludedClasses];
            _resultNames pushBack _customName;
        } forEach configProperties [_x];
    } forEach configProperties [_baseConfig >> XEH_FORMAT_CONFIG_NAME(_eventName), "isClass _x"];
} forEach [XEH_EVENTS];

TRACE_2("compiled",_baseConfig,count _result);

_result select {(_x select 2) isNotEqualTo [{},{},{}]}

#include "script_component.hpp"
/* ----------------------------------------------------------------------------
Internal Function: CBA_fnc_preInit

Description:
    Occurs once per mission before objects are initialized.
    Internal use only.

Parameters:
    None

Returns:
    None

Author:
    commy2
---------------------------------------------------------------------------- */

if (ISPROCESSED(missionNamespace)) exitWith {
    XEH_LOG("preInit already executed. Abort preInit.");
};
SETPROCESSED(missionNamespace);

SLX_XEH_DisableLogging = uiNamespace getVariable ["SLX_XEH_DisableLogging", false]; // get from preStart

XEH_LOG("PreInit started. v" + getText (configFile >> "CfgPatches" >> "cba_common" >> "versionStr"));

SLX_XEH_STR = ""; // does nothing, never changes, backwards compatibility
SLX_XEH_COMPILE = compileFinal "diag_log text format ['[CBA-XEH] old SLX_XEH_COMPILE macro used on %1', _this]; compileScript [_this]"; //backwards compat
SLX_XEH_COMPILE_NEW = CBA_fnc_compileFunction; //backwards comp
SLX_XEH_DUMMY = "Logic"; // backwards comp

SLX_XEH_MACHINE = [ // backwards compatibility, deprecated
    !isDedicated, // 0 - isClient (and thus has player)
    didJIP, // 1 - isJip
    !isServer, // 2 - isDedicatedClient (and thus not a Client-Server)
    isServer, // 3 - isServer
    isDedicated, // 4 - isDedicatedServer (and thus not a Client-Server)
    false, // 5 - Player Check finished, no longer works
    !isMultiplayer, // 6 - isSingleplayer
    false, // 7 - PreInit passed
    false, // 8 - PostInit passed
    isMultiplayer, // 9 - Multiplayer && respawn
    if (isDedicated) then {0} else {[2, 1] select isServer}, // 10 - Machine type (only 3 possible configurations)
    0, // 11 - SESSION_ID
    0, // 12 - LEVEL - Used for version determination
    false, // 13 - TIMEOUT - PostInit timedOut, always false
    productVersion, // 14 - Game
    3 // 15 - Product+Version, always Arma 3
];

CBA_isHeadlessClient = !hasInterface && !isDedicated;

// make case insensitive list of all supported events
GVAR(EventsLowercase) = [];
{
    private _header = "";
    #ifndef SKIP_SCRIPT_NAME
        _header = format ["scriptName 'XEH:%1';", _x];
    #endif
    // generate event functions
    switch _x do {
        case "Init": {
            FUNC(Init) = compileFinal (_header + "(_this select 0) call CBA_fnc_initEvents; (_this select 0) call CBA_fnc_init");
        };
        // This prevents double execution of the Killed event on the same unit.
        case "Killed": {
            FUNC(Killed) = compileFinal (_header + format ['\
                params ["_unit"];\
                if (_unit getVariable [QGVAR(killedBody), objNull] != _unit) then {\
                    _unit setVariable [QGVAR(killedBody), _unit];\
                    private "_unit";\
                    {call _x} forEach ((_this select 0) getVariable QGVAR(%1));\
                };',
            _x]);
        };
        case "HitPart": {
            FUNC(HitPart) = compileFinal (_header + format ['{call _x} forEach ((_this select 0 select 0) getVariable QGVAR(%1))', _x]);
        };
        default {
            missionNamespace setVariable [
                format [QFUNC(%1), _x],
                compileFinal (_header + format ['{call _x} forEach ((_this select 0) getVariable QGVAR(%1))', _x])
            ];
        };
    };

    GVAR(EventsLowercase) pushBack toLower _x;
} forEach [XEH_EVENTS];

// generate list of incompatible classes
GVAR(incompatible) = [] call CBA_fnc_createNamespace;

{
    private _class = configFile >> "CfgVehicles" >> _x;

    while {isClass _class && {!ISINCOMP(configName _class)}} do {
        SETINCOMP(configName _class);

        _class = inheritsFrom _class;
    };
} forEach call (uiNamespace getVariable [QGVAR(incompatibleClasses), {[]}]);

// always recompile extended event handlers
#ifdef DEBUG_MODE_FULL
    XEH_LOG("Compiling XEH START");
#endif

//Get configFile eventhandlers from cache that was generated at preStart
GVAR(allEventHandlers) = call (uiNamespace getVariable [QGVAR(configFileEventHandlers), {[]}]);

{
    GVAR(allEventHandlers) append (_x call CBA_fnc_compileEventHandlers);
} forEach [campaignConfigFile, missionConfigFile];

#ifdef DEBUG_MODE_FULL
    XEH_LOG("Compiling XEH END");
#endif

// add extended event handlers to classes
GVAR(fallbackRunning) = false;

// call PreInit events and add event handlers to object classes
{
    if (_x select 0 == "") then {
        if (_x select 1 == "preInit") then {
            (_x select 2) call {
                private "_x";

                [] call (_this select 0);

                if (!isDedicated) then {
                    [] call (_this select 1);
                };

                if (isServer) then {
                    [] call (_this select 2);
                };
            };
        };
    } else {
        _x params ["_className", "_eventName", "_eventFunc", "_allowInheritance", "_excludedClasses"];

        // backwards comp, args in _this are already switched
        if (_eventName == "firedBis") then {
            _eventName = "fired";
        };

        _eventFunc params ["_funcAll", "_funcClient", "_funcServer"];

        if (_funcAll isNotEqualTo {}) then {
            private _success = [_className, _eventName, _funcAll, _allowInheritance, _excludedClasses] call CBA_fnc_addClassEventHandler;
            TRACE_3("addClassEventHandler",_className,_eventName,_success);
        };

        if (!isDedicated && {_funcClient isNotEqualTo {}}) then {
            private _success = [_className, _eventName, _funcClient, _allowInheritance, _excludedClasses] call CBA_fnc_addClassEventHandler;
            TRACE_3("addClassEventHandler",_className,_eventName,_success);
        };

        if (isServer && {_funcServer isNotEqualTo {}}) then {
            private _success = [_className, _eventName, _funcServer, _allowInheritance, _excludedClasses] call CBA_fnc_addClassEventHandler;
            TRACE_3("addClassEventHandler",_className,_eventName,_success);
        };
    };
} forEach GVAR(allEventHandlers);

GVAR(initPostStack) = [];

#ifdef DEBUG_MODE_FULL
    diag_log text format ["isScheduled = %1", call CBA_fnc_isScheduled];
#endif

SLX_XEH_MACHINE set [7, true]; // PreInit passed

#ifdef DEBUG_MODE_FULL
    [QGVAR(LoadingScreenStarted), {diag_log [QGVAR(LoadingScreenStarted), _this]}] call CBA_fnc_addEventHandler;
    [QGVAR(LoadingScreenEnded), {diag_log [QGVAR(LoadingScreenEnded), _this]}] call CBA_fnc_addEventHandler;
#endif

// CBA_loadingScreenDone event
GVAR(expectedLoadingScreens) = ["bis_fnc_preload", "bis_fnc_initRespawn"];

if (!isServer) then { // only on client
    GVAR(expectedLoadingScreens) pushBack "bis_fnc_initFunctions";
};

// check if this was the last loading screen, if so, fire event
[QGVAR(LoadingScreenEnded), {
    params ["_loadingScreen"];

    if (!isNil QGVAR(expectedLoadingScreens)) then {
        GVAR(expectedLoadingScreens) deleteAt (GVAR(expectedLoadingScreens) find _loadingScreen);

        if (GVAR(expectedLoadingScreens) isEqualTo []) then {
            GVAR(expectedLoadingScreens) = nil;
            ["CBA_loadingScreenDone", []] call CBA_fnc_localEvent;
        };
    };
}] call CBA_fnc_addEventHandler;

#ifdef DEBUG_MODE_FULL
    ["CBA_loadingScreenDone", {
        playSound "Beep_Target";
    }] call CBA_fnc_addEventHandler;
#endif

XEH_LOG("PreInit finished.");

#include "script_component.hpp"
/* ----------------------------------------------------------------------------
Function: CBA_fnc_execNextFrame

Description:
    Executes a code once in non sched environment on the next frame.

Parameters:
    _function - The function to run. <CODE>
    _args     - Parameters passed to the function executing. This will be the same array every execution. (optional, default: []) <ANY>

Returns:
    Nothing Useful

Examples:
    (begin example)
        [{player sideChat format ["This is frame %1, not %2", diag_frameNo, _this select 0];}, [diag_frameNo]] call CBA_fnc_execNextFrame;
    (end)

Author:
    esteldunedain and PabstMirror, donated from ACE3
---------------------------------------------------------------------------- */

params [["_function", {}, [{}]], ["_args", []]];

if (diag_frameNo != GVAR(nextFrameNo)) then {
    GVAR(nextFrameBufferA) pushBack [_args, _function];
} else {
    GVAR(nextFrameBufferB) pushBack [_args, _function];
};

#include "..\script_component.hpp"
/*
 * Author: KoffeinFlummi, commy2
 * Checks if a vehicle is equipped with an FCS and if so, adds the fired event handler. Execute on server.
 *
 * Arguments:
 * 0: Vehicle <OBJECT>
 *
 * Return Value:
 * None
 *
 * Example:
 * [car] call ace_fcs_fnc_vehicleInit
 *
 * Public: No
 */

params ["_vehicle"];

{
    private _turretConfig = [configOf _vehicle, _x] call EFUNC(common,getTurretConfigPath);

    if (getNumber (_turretConfig >> QGVAR(Enabled)) == 1) then {
        if (isNil QGVAR(jipID)) then {
            GVAR(jipID) = [QGVAR(addFiredEH), [], QGVAR(addFiredEH)] call CBA_fnc_globalEventJIP;
            TRACE_1("Adding fired EH for players",GVAR(jipID));
        };

        _vehicle setVariable [format ["%1_%2", QGVAR(Distance),  _x],  0, true];
        _vehicle setVariable [format ["%1_%2", QGVAR(Magazines), _x], [], true];
        _vehicle setVariable [format ["%1_%2", QGVAR(Elevation), _x], [], true];
        _vehicle setVariable [format ["%1_%2", QGVAR(Azimuth),   _x],  0, true];

        // calculate offset between gunner camera and muzzle position
        if !(_vehicle isKindOf "Air") then {

            private _gunBeg = getText (_turretConfig >> "gunBeg");
            private _gunnerView = getText (_turretConfig >> "memoryPointGunnerOptics");

            private _gunBegPos = (_vehicle selectionPosition _gunBeg) select 0;
            private _gunnerViewPos = (_vehicle selectionPosition _gunnerView) select 0;
            private _viewDiff = _gunBegPos - _gunnerViewPos;

            _vehicle setVariable [format ["%1_%2", QGVAR(ViewDiff), _x], _viewDiff, true];
        } else {
            _vehicle setVariable [format ["%1_%2", QGVAR(ViewDiff), _x],         0, true];
        };
    };
} forEach allTurrets _vehicle;

#include "script_component.hpp"
/* ----------------------------------------------------------------------------
Function: CBA_fnc_getTurret

Description:
    A function used to find out which config turret is turretpath.

Parameters:
    _vehicle    - Vehicle or vehicle class name or vehicle config <STRING, OBJECT, CONFIG>
