#include "..\script_component.hpp"
/*
 * Author: BaerMitUmlaut
 * Finds the turret that has control over the marking laser.
 *
 * Arguments:
 * 0: Aircraft config <CONFIG>
 *
 * Return Value:
 * <ARRAY>
 *
 * Example:
 * [configOf _plane] call ace_markinglaser_fnc_findTurret
 *
 * Public: No
 */

params ["_config"];

private _copilotPath = nil;
private _copilotConfig = configNull;
private _primaryPath = nil;
private _primaryConfig = configNull;
private _isUAV = getNumber (_config >> "isUAV") == 1;

private _walkTurrets = {
    params ["_path", "_turrets"];

    {
        // Check turret rotation for symmetry, filters door gunner turrets
        if (abs getNumber (_x >> "minTurn") != abs getNumber (_x >> "maxTurn")) then {
            continue;
        };

        // Check if turret has a optics with night or thermal vision
        private _visionModes = flatten (("true" configClasses (_x >> "OpticsIn")) apply {
            (getArray (_x >> "visionMode")) apply {toLowerANSI _x}
        });

        if !("nvg" in _visionModes || {"ti" in _visionModes}) then {
            continue;
        };

        // Use copilot turret if possible
        // Not all helicopter gun turrets use this flag (for example the Kajman)
        if (getNumber (_x >> "isCopilot") == 1) then {
            _copilotPath = _path + [_forEachIndex];
            _copilotConfig = _x;
            break;
        };

        // Fallback to primary gunner
        if (isNil "_primaryPath" && {getNumber (_x >> "primaryGunner") == 1}) then {
            _primaryPath = _path + [_forEachIndex];
            _primaryConfig = _x;
        };

        // Search subturrets
        if (isClass (_x >> "Turrets")) then {
            private _turrets = "true" configClasses (_x >> "Turrets");
            [_path + [_forEachIndex], _turrets] call _walkTurrets;
        };
    } forEach _turrets;
};

[[], "true" configClasses (_config >> "Turrets")] call _walkTurrets;

if (!isNil "_copilotPath") exitWith {
    [_copilotPath, _copilotConfig]
};
if (!isNil "_primaryPath") exitWith {
    [_primaryPath, _primaryConfig]
};

[]

#include "script_component.hpp"
/* ----------------------------------------------------------------------------
Function: CBA_statusEffects_fnc_localEH
Description:
    Handles locality switch, runs a respawn check and then reapplies all effect events.

Parameters:
    _object  - Vehicle that it will be attached to (player or vehicle) <OBJECT>
    _isLocal - Is local <BOOL>

Returns:
    None

Examples
    (begin example)
        [player, true] call CBA_statusEffects_fnc_localEH
    (end)

Author:
    PabstMirror
---------------------------------------------------------------------------- */
SCRIPT(localEH);
params ["_object", "_isLocal"];

// Only run this after the settings are initialized
// Need to wait for all EH to be installed (local event will happen between pre and post init)
if !(missionNamespace getVariable [QEGVAR(settings,ready), false]) exitWith {
    TRACE_1("pushing to runAtSettingsInitialized",_this);
    EGVAR(settings,runAtSettingsInitialized) pushBack [FUNC(localEH), _this];
};

if (!_isLocal) exitWith { TRACE_1("object no longer local",_this) };
if (isNull _object) exitWith { TRACE_1("object null",_this) };

// Reset any variables because of respawn
[_object, false] call FUNC(resetVariables);

// Send all Variables to client
[_object, ""] call FUNC(sendEffects);

#include "script_component.hpp"
/* ----------------------------------------------------------------------------
Function: CBA_statusEffects_fnc_resetVariables
Description:
    Resets all effect numbers to 0 when an object respawns (but does not apply the effect event).

Parameters:
    _object       - Vehicle that it will be attached to (player or vehicle) <OBJECT>
    _setObjectRef - Explicitly set object reference (optional, default: false) <BOOL>

Returns:
    None

Examples
    (begin example)
        [player, true] call CBA_statusEffects_fnc_resetVariables
    (end)

Author:
    PabstMirror
---------------------------------------------------------------------------- */
SCRIPT(resetVariables);
params [
    ["_object", objNull, [objNull]],
    ["_setObjectRef", false, [false]]
];

if (isNull _object) exitWith {};

private _objectRef = _object getVariable QGVAR(object);
TRACE_2("testing",_object,_objectRef);

// If nothing was ever set, or objects match, exit (always true unless respawned)
if (isNil "_objectRef") exitWith {
    if (_setObjectRef) then {
        _object setVariable [QGVAR(object), _object, true]; // Explicitly set new object ref
    };
};
if (_object == _objectRef) exitWith {};

// Mismatch, so if effect has ever been defined, reset to 0
{
    private _effectVarName = format [QGVAR(effect_%1), _x];
    private _effectNumber = _object getVariable [_effectVarName, -1];
    if (_effectNumber != -1) then {
        TRACE_2("forced reset defined array on object mismatch",_x,_effectNumber);
        _object setVariable [_effectVarName, 0, true]; // This always resets to 0 (not -1/nil)!
    };
} forEach GVAR(statusEffects);

_object setVariable [QGVAR(statusEffect_object), _object, true];

#include "script_component.hpp"
/* ----------------------------------------------------------------------------
Function: CBA_statusEffects_fnc_sendEffects
Description:
    Sends all status effects for an object (can be run on non-local objects)

Parameters:
    _object     - Object <OBJECT>
    _effectName - Effect name (or "" to send all) <STRING>

Returns:
    None

Examples
    (begin example)
        [player, ""] call CBA_statusEffects_fnc_sendEffects
    (end)

Author:
    PabstMirror
---------------------------------------------------------------------------- */
SCRIPT(sendEffects);
params [
    ["_object", objNull, [objNull]],
    ["_effectName", "", [""]]
];

if (isNull _object) exitWith {};

if (_effectName == "") exitWith { // Recurse through all possible effects
    {
        [_object, _x] call FUNC(sendEffects)
    } forEach (keys GVAR(statusEffects));
};


private _effectVarName = format [QGVAR(effect_%1), _effectName];
private _effectNumber = _object getVariable [_effectVarName, -1];

// We only do anything if the effect has been defined at some point in the game for this unit
TRACE_2("checking if event is nil",_effectName,_effectNumber);
if (_effectNumber != -1) then {
    (GVAR(statusEffects) get toLowerANSI _effectName) params ["_isGlobal", "_sendJIP", "_eventName"];
    switch (true) do {
        case (_sendJIP): {
            TRACE_3("Sending Global JIP Event",_object,_effectNumber,_eventName);
            private _jipID = format [QGVAR(effect_%1_%2), _eventName, hashValue _object];
            [_eventName, [_object, _effectNumber], _jipID] call CBA_fnc_globalEventJIP;
            [_jipID, _object] call CBA_fnc_removeGlobalEventJIP;
        };
        case (_isGlobal): {
            TRACE_3("Sending Global Event",_object,_effectNumber,_eventName);
            [_eventName, [_object, _effectNumber]] call CBA_fnc_globalEvent;
        };
        default {
            TRACE_3("Sending Target Event",_object,_effectNumber,_eventName);
            [_eventName, [_object, _effectNumber], _object] call CBA_fnc_targetEvent;
        };
    };
};

